'use strict';
// Go's file rules (src/languages/go/rules.js, G1): source, test and generated files as
// the go tool sees them.
const test = require('node:test');
const assert = require('node:assert/strict');
const { goRules, GENERATED_HEAD_CHARS } = require('../src/languages/go/rules');

test('a .go file is Go source; testdata and vendor are not the change under review', () => {
  for (const p of ['main.go', 'pkg/cmd/pr/view.go', 'internal/config/refreshable_test.go', 'a\\b\\c.go']) assert.equal(goRules.handles(p), true, p);
  for (const p of ['main.ts', 'go.mod', 'go.sum', 'a.go.txt', 'pkg/testdata/fixture.go', 'testdata/x.go', 'vendor/github.com/x/y.go', 'a\\vendor\\b.go']) {
    assert.equal(goRules.handles(p), false, p);
  }
});

test('a test is a _test.go file, wherever it is', () => {
  assert.equal(goRules.isTest('internal/config/refreshable_test.go'), true);
  assert.equal(goRules.isTest('pkg/x/x_test.go'), true);
  assert.equal(goRules.isTest('pkg/x/testing.go'), false);
  assert.equal(goRules.isTest('pkg/x/test.go'), false, 'not a _test.go name');
});

test('generated by name: protocol buffers and generator suffixes', () => {
  for (const p of ['api/v1/service.pb.go', 'api/v1/service.pb.gw.go', 'x/zz_generated.deepcopy.go', 'x/types_gen.go', 'x/mock_generated.go']) {
    assert.equal(goRules.isGenerated(p, 'package x\n'), true, p);
  }
  assert.equal(goRules.isGenerated('x/generator.go', 'package x\n'), false);
});

test('generated by the go tool\'s comment, only before the package clause and only exactly', () => {
  const marked = '// Code generated by mockgen. DO NOT EDIT.\n\npackage x\n';
  assert.equal(goRules.isGenerated('x/mock.go', marked), true);
  assert.equal(goRules.isGenerated('x/mock.go', '// Copyright 2024\n\n// Code generated by stringer; DO NOT EDIT.\npackage x\n'), true);
  assert.equal(goRules.isGenerated('x/mock.go', marked.replace(/\n/g, '\r\n')), true, 'CRLF line ends');
  assert.equal(goRules.isGenerated('x/a.go', 'package x\n\n// Code generated by hand. DO NOT EDIT.\n'), false, 'after the package clause');
  assert.equal(goRules.isGenerated('x/a.go', '// code generated by x. DO NOT EDIT.\npackage x\n'), false, 'the go tool matches case');
  assert.equal(goRules.isGenerated('x/a.go', '// Code generated by x. Do not edit.\npackage x\n'), false);
  assert.equal(goRules.isGenerated('x/a.go', ''), false, 'an empty file');
});

test('the generated comment is looked for only in the head of the file', () => {
  const late = `${'// filler\n'.repeat(Math.ceil(GENERATED_HEAD_CHARS / 10))}// Code generated by x. DO NOT EDIT.\npackage x\n`;
  assert.equal(goRules.isGenerated('x/a.go', late), false, 'past the head: analysed, as documented');
});
